  const availH=wrap.clientHeight-(parseFloat(cs.paddingTop)||0)-(parseFloat(cs.paddingBottom)||0);
  const s = Math.min(availW/WNAT, availH/HNAT);
  cv.style.width = (WNAT*s)+'px'; cv.style.height = (HNAT*s)+'px';
