// ================= CRT post-process (WebGL, single pass, Pi-friendly) =================
let crtOn=false, crtGL=null, crtFailed=false;
const CRT_VERT = `
attribute vec2 aPos;
varying vec2 vUV;
void main(){ vUV = aPos*0.5+0.5; gl_Position = vec4(aPos,0.0,1.0); }`;
const CRT_FRAG = `
precision highp float;
varying vec2 vUV;
uniform sampler2D uTex;
uniform vec2 uSrc;   // source (game) resolution
uniform vec2 uOut;   // output resolution
// gentle barrel curvature (tube bulge)
vec2 curve(vec2 uv){
  uv = uv*2.0-1.0;
  vec2 off = abs(uv.yx)/vec2(7.0, 5.5);
  uv += uv*off*off;
  return uv*0.5+0.5;
}
float gaus(float x, float s){ return exp(-(x*x)/(2.0*s*s)); }
// one phosphor scanline: horizontal gaussian in SOURCE pixels (CRTs are
// continuous horizontally — detail survives; only vertical is quantized)
vec3 lineSample(float ux, float yc, float sig, float stride){
  vec3 acc=vec3(0.0); float wt=0.0;
  for(int i=-2;i<=2;i++){
    float ox=float(i)*stride;
    float w=gaus(ox,sig);
    acc+=texture2D(uTex, vec2(ux+ox/uSrc.x, yc)).rgb*w; wt+=w;
  }
  return acc/wt;
}
void main(){
  vec2 uv = curve(vUV);
  if(uv.x<0.0||uv.x>1.0||uv.y<0.0||uv.y>1.0){ gl_FragColor=vec4(0.0,0.0,0.0,1.0); return; }
  // scanlines every 2 source px (matches the art's pixel size; eyes stay on a line)
  float Vy = uSrc.y/2.0;
  float py = uv.y*Vy - 0.5;
  float y0 = floor(py), fy = py - y0;
  float ycA=(y0+0.5)/Vy, ycB=(y0+1.5)/Vy;
  // pixel body: crisp horizontal with a soft beam-spot blur (sigma < 1 source px)
  vec3 cA = lineSample(uv.x, ycA, 0.55, 1.0);
  vec3 cB = lineSample(uv.x, ycB, 0.55, 1.0);
  // beam width grows with brightness -> bright pixels halo (Lottes trick)
  float lA = dot(cA,vec3(0.30,0.55,0.15));
  float lB = dot(cB,vec3(0.30,0.55,0.15));
  float wA = gaus(fy,     0.30+0.20*lA);
  float wB = gaus(1.0-fy, 0.30+0.20*lB);
  vec3 col = cA*wA + cB*wB;
  // crisp detail layer: pull small dark features (eyes!) back through the glow
  vec3 sharp = texture2D(uTex, uv).rgb;
  col = mix(col, sharp*max(wA,wB), 0.42);
  // soft wide bloom, gated by local darkness: glow spreads AROUND bright pixels
  // but never pours INTO dark details (keeps eyes/mouth black)
  float dark = smoothstep(0.02, 0.30, dot(sharp,vec3(0.30,0.55,0.15)));
  vec3 gA = lineSample(uv.x, ycA, 2.2, 2.0);
  vec3 gB = lineSample(uv.x, ycB, 2.2, 2.0);
  col += (gA*gaus(fy,0.60) + gB*gaus(1.0-fy,0.60)) * 0.24 * (0.30+0.70*dark);
  // subtle aperture grille (keeps vibrance, still reads as phosphor stripes)
  float ph = mod(vUV.x*uOut.x, 3.0);
  vec3 mask = vec3(0.87);
  if(ph<1.0) mask.r=1.0; else if(ph<2.0) mask.g=1.0; else mask.b=1.0;
  col *= mask;
  // vibrance: brightness + saturation boost instead of the old washy gamma lift
  col *= 1.16;
  float lum = dot(col,vec3(0.30,0.55,0.15));
  col = mix(vec3(lum), col, 1.18);
  // vignette / tube edge falloff (kept)
  vec2 vg = vUV*(1.0-vUV.yx);
  float vig = pow(clamp(vg.x*vg.y*32.0,0.0,1.0), 0.22);
  col *= vig;
  gl_FragColor = vec4(clamp(col,0.0,1.0), 1.0);
}`;
function crtCompile(gl, type, src){
  const sh=gl.createShader(type); gl.shaderSource(sh,src); gl.compileShader(sh);
  if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS)){ console.warn('CRT shader:',gl.getShaderInfoLog(sh)); return null; }
  return sh;
}
function initCRT(){
  if(crtGL||crtFailed) return;
  const g=document.getElementById('glcv');
  const gl=g.getContext('webgl',{antialias:false,preserveDrawingBuffer:false,alpha:false});
  if(!gl){ crtFailed=true; return; }
  const vs=crtCompile(gl,gl.VERTEX_SHADER,CRT_VERT), fs=crtCompile(gl,gl.FRAGMENT_SHADER,CRT_FRAG);
  if(!vs||!fs){ crtFailed=true; return; }
  const prog=gl.createProgram(); gl.attachShader(prog,vs); gl.attachShader(prog,fs); gl.linkProgram(prog);
  if(!gl.getProgramParameter(prog,gl.LINK_STATUS)){ crtFailed=true; return; }
  gl.useProgram(prog);
  const buf=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,buf);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1, 1,-1, -1,1, 1,1]),gl.STATIC_DRAW);
  const aPos=gl.getAttribLocation(prog,'aPos'); gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos,2,gl.FLOAT,false,0,0);
  const tex=gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D,tex);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);
  crtGL={canvas:g, gl, prog, tex,
    uSrc:gl.getUniformLocation(prog,'uSrc'),
    uOut:gl.getUniformLocation(prog,'uOut'),
    uTex:gl.getUniformLocation(prog,'uTex')};
  gl.uniform1i(crtGL.uTex,0);
}
function drawCRT(){
  if(crtFailed) { crtOn=false; document.getElementById('glcv').style.display='none'; return; }
  if(!crtGL) initCRT();
  if(!crtGL) return;
  const g=crtGL.canvas, gl=crtGL.gl;
  // overlay exactly on top of the game canvas
  const r=cv.getBoundingClientRect();
  const dpr=Math.min(window.devicePixelRatio||1, 2);
  const ow=Math.max(1,Math.round(r.width*dpr)), oh=Math.max(1,Math.round(r.height*dpr));
  g.style.left=r.left+'px'; g.style.top=r.top+'px';
  g.style.width=r.width+'px'; g.style.height=r.height+'px';
  if(g.width!==ow||g.height!==oh){ g.width=ow; g.height=oh; }
  gl.viewport(0,0,ow,oh);
  gl.bindTexture(gl.TEXTURE_2D,crtGL.tex);
  gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,cv);
  gl.uniform2f(crtGL.uSrc,WNAT,HNAT);
  gl.uniform2f(crtGL.uOut,ow,oh);
  gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
}
function applyCRT(on){
  crtOn=!!on;
  const g=document.getElementById('glcv');
  if(crtOn && !crtFailed){ g.style.display='block'; cv.style.opacity='0.001'; }
  else { g.style.display='none'; cv.style.opacity='1'; }
}

