// ---------- sprite decoding ----------
function decode(s){
  const c = document.createElement('canvas');
  c.width = s.w; c.height = s.h;
  const g = c.getContext('2d');
  const img = g.createImageData(s.w, s.h);
  
  if (s.rle) {
    const raw = atob(s.rle);
    let i = 0, px = 0;
    while(i < raw.length) {
      const val = raw.charCodeAt(i++);
      const count = raw.charCodeAt(i++);
      for(let k=0; k<count; k++) {
        if(val !== 255) {
          const o = px * 4;
          const p = s.pal[val];
          img.data[o]=p[0]; img.data[o+1]=p[1]; img.data[o+2]=p[2]; img.data[o+3]=255;
        }
        px++;
      }
    }
  } else {
    for(let y=0;y<s.h;y++)for(let x=0;x<s.w;x++){
      const k = s.px[y][x];
      if(k<0) continue;
      const o = (y*s.w+x)*4, p = s.pal[k];
      img.data[o]=p[0]; img.data[o+1]=p[1]; img.data[o+2]=p[2]; img.data[o+3]=255;
    }
  }
  g.putImageData(img,0,0);
  return c;
}

const flip = (c) => {
  const fc = document.createElement('canvas');
  fc.width = c.width; fc.height = c.height;
  const fg = fc.getContext('2d');
  fg.translate(c.width, 0); fg.scale(-1, 1);
  fg.drawImage(c, 0, 0);
  return fc;
};

const SPR = {};
for(const k in ASSETS) {
  SPR[k] = decode(ASSETS[k]);
  SPR[k+'_flip'] = flip(SPR[k]);
}

// ---------- dirt texture ----------
function makeDirt(grid){
  // texture matched to the source screenshots: dark chocolate base,
  // small warm squiggle speckles (2-3px), ragged bitten edges
  const ROWS=grid.length, COLS=grid[0].length;
  const solidCell=(i,j)=>(i<0||j<0||i>=COLS||j>=ROWS)?true:grid[j][i]===1;
  const c = document.createElement('canvas');
  c.width = COLS*T; c.height = ROWS*T;
  const g = c.getContext('2d');
  let seed = 987654321;
  const rnd = ()=> (seed = (seed*1103515245+12345)&0x7fffffff)/0x7fffffff;
  const BG = '#070402';
  const PX = 6;   // soft chunky dirt pixels (the look you liked)
  for(let j=0;j<ROWS;j++)for(let i=0;i<COLS;i++){
    if(!solidCell(i,j)) continue;
    for(let y=j*T;y<(j+1)*T;y+=PX)for(let x=i*T;x<(i+1)*T;x+=PX){
      const r = rnd();
      let col;
      if(r<0.42) col='#4c2c10';
      else if(r<0.68) col='#553314';
      else if(r<0.85) col='#5f3a18';
      else if(r<0.95) col='#6c451f';
      else col='#7d5428';
      g.fillStyle = col;
      g.fillRect(x,y,PX,PX);
    }
  }
  // ragged bitten edges toward corridors
  g.fillStyle = BG;
  for(let j=0;j<ROWS;j++)for(let i=0;i<COLS;i++){
    if(!solidCell(i,j)) continue;
    for(const [dx,dy] of [[0,-1],[0,1],[-1,0],[1,0]]){
      if(solidCell(i+dx,j+dy)) continue;
      for(let k=0;k<T;){
        const run = 2+(rnd()*4|0);            // notch length
        if(rnd()<0.5){
          const depth = 1+(rnd()*2|0);        // notch depth
          let x,y,w,h;
          if(dy===-1){x=i*T+k;y=j*T;w=run;h=depth;}
          else if(dy===1){x=i*T+k;y=(j+1)*T-depth;w=run;h=depth;}
          else if(dx===-1){x=i*T;y=j*T+k;w=depth;h=run;}
          else {x=(i+1)*T-depth;y=j*T+k;w=depth;h=run;}
          g.fillRect(x,y,w,h);
        }
        k += run + 2 + (rnd()*3|0);
      }
    }
  }
  return c;
}
const DIRT_CACHE=new Map();
function dirtFor(grid){
  if(!DIRT_CACHE.has(grid)) DIRT_CACHE.set(grid, makeDirt(grid));
  return DIRT_CACHE.get(grid);
}

// ---------- surface walker ----------
// normal n: unit vector pointing away from surface into open space
// facing: +1/-1 along tangent; tangent(n) = rotate n by +90deg (clockwise on screen)
const tangent = n => ({x:-n.y, y:n.x});
function keyOf(n){ return n.x+','+n.y; }

// ---------- AABB platformer physics ----------
class Body{
  constructor(x,y){
    this.x=x; this.y=y;               
    this.vx=0; this.vy=0;             
    this.w=16; this.h=32;
    this.face=1;                      
    this.air=false;
    this.animT=0;
    this.animState='idle';
    this.jheld=false;
    this.coyote=0;
    this.jumpBuf=0;
  }
  
  step(pad){
    const MAX_RUN=1.9, ACC=0.12, FRIC=0.80, SKID=0.30;
    const JUMP=4.2, GRAV_UP=0.13, GRAV_DN=0.30, TERM=4.5, AIR_CTRL=0.10;
    
    if(this.air){
      this.vy += (this.vy < 0 && this.jheld) ? GRAV_UP : GRAV_DN;
      if(this.vy > TERM) this.vy = TERM;
    } else {
      this.vy = 0;
      this.coyote = 6;
    }
    
    pad.prevJump = pad.prevJump || false;
    const justJump = pad.jump && !pad.prevJump;
    if(justJump) this.jumpBuf = 6;
    pad.prevJump = pad.jump;
    
    if(this.jumpBuf > 0 && this.coyote > 0){
      this.vy = -JUMP;
      this.air = true;
      this.coyote = 0;
      this.jumpBuf = 0;
    }
    if(this.jumpBuf > 0) this.jumpBuf--;
    if(this.coyote > 0) this.coyote--;
    
    this.jheld = pad.jump;
    
    let ix = pad.gx;
    if(ix !== 0){
      this.face = ix;
      let acc = this.air ? AIR_CTRL : (Math.sign(this.vx) !== ix ? SKID : ACC);
      this.vx += ix * acc;
      if(this.vx > MAX_RUN) this.vx = MAX_RUN;
      if(this.vx < -MAX_RUN) this.vx = -MAX_RUN;
      this.animState = 'walk';
    } else {
      if(!this.air) this.vx *= FRIC;
      if(Math.abs(this.vx) < 0.1) this.vx = 0;
      this.animState = 'idle';
    }
    if(this.air) this.animState = 'jump';
    
    // Y Collision
    this.y += this.vy;
    let head = Math.floor((this.y - this.h)/T);
    let feet = Math.floor(this.y/T);
    let l = Math.floor((this.x - this.w/2 + 1)/T);
    let r = Math.floor((this.x + this.w/2 - 1)/T);
    
    this.air = true;
    if(this.vy > 0) { // falling
      if(solidCell(l, feet) || solidCell(r, feet)){
        this.y = feet * T;
        this.vy = 0;
        this.air = false;
      }
    } else if(this.vy < 0) { // jumping up
      if(solidCell(l, head) || solidCell(r, head)){
        this.y = (head + 1) * T + this.h;
        this.vy = 0;
      }
    }
    
    // X Collision
    this.x += this.vx;
    head = Math.floor((this.y - this.h + 1)/T);
    feet = Math.floor((this.y - 1)/T);
    l = Math.floor((this.x - this.w/2)/T);
    r = Math.floor((this.x + this.w/2)/T);
    
    if(this.vx > 0){ // moving right
      if(solidCell(r, head) || solidCell(r, feet)){
        this.x = r * T - this.w/2;
        this.vx = 0;
      }
    } else if(this.vx < 0){ // moving left
      if(solidCell(l, head) || solidCell(l, feet)){
        this.x = (l + 1) * T + this.w/2;
        this.vx = 0;
      }
    }
    
    if(this.x < this.w/2) { this.x = this.w/2; this.vx = 0; }
    if(this.x > NI*T - this.w/2) { this.x = NI*T - this.w/2; this.vx = 0; }
    
    this.animT++;
  }
}
// ---------- ring AI ----------
function bossStep(){
  ring.x = camX + WNAT - 40; // Boss chases from right
  ring.y = Math.sin(Date.now()/200)*10 + HNAT/2;
  return; // Skip old logic

  const D=curDiff();
  if(ring.tpCd>0) ring.tpCd--;

  // --- teleport animation in progress (EXPERT): freeze normal movement ---
  if(ring.tpPhase>0){
    ring.tpT++;
    const OUT=8;
    if(ring.tpPhase===1 && ring.tpT>=OUT){
      // relocate to the safest far cell at the midpoint
      ring.tx=ring.tpX; ring.ty=ring.tpY;
      ring.x=(ring.tx+0.5)*T; ring.y=(ring.ty+0.5)*T; ring.prev=null;
      ring.tpPhase=2; ring.tpT=0;
    } else if(ring.tpPhase===2 && ring.tpT>=8){
      ring.tpPhase=0; ring.tpCd=D.tpCool||150;
    }
    ring.bob+=0.05;
    return;
  }

  // target cell center
  const cx=(ring.tx+0.5)*T, cy=(ring.ty+0.5)*T;
  const dx=cx-ring.x, dy=cy-ring.y;
  const d=Math.hypot(dx,dy);
  if(d<ring.speed){
    ring.x=cx; ring.y=cy;

    // --- EXPERT: teleport when cornered (occasionally, on a cooldown) ---
    if(D.teleport && ring.tpCd<=0){
      const here=Math.min(distR?distR[ring.ty][ring.tx]:99,
                          distB?distB[ring.ty][ring.tx]:99);
      if(here<=(D.tpNear||4) && Math.random()<(D.tpChance||0.6)){
        // pick the open cell that maximises min-distance from all players
        let bi=ring.tx,bj=ring.ty,bs=-1;
        for(let j=0;j<NJ;j++)for(let i=0;i<NI;i++){
          if(LAY.maze[j][i]===1) continue;
          const dd=Math.min(distR?distR[j][i]:99, distB?distB[j][i]:99);
          if(dd>bs){ bs=dd; bi=i; bj=j; }
        }
        if(bs>=6){ ring.tpX=bi; ring.tpY=bj; ring.tpPhase=1; ring.tpT=0; ring.bob+=0.05; return; }
      }
    }

    // choose next cell
    let best=null, bestScore=-1e9;
    if(D.algo==='smart'){
      // blocked = players' current + predicted cells (don't route through them)
      const blocked=new Set();
      const [rc,rr]=cellOf(player); blocked.add(rc+','+rr);
      const [pri,prj]=predictedCell(player,D.predict); blocked.add(pri+','+prj);
      if(blueW){ const [bc,br]=cellOf(blueW); blocked.add(bc+','+br);
                 const [pbi,pbj]=predictedCell(blueW,D.predict); blocked.add(pbi+','+pbj); }
      for(const[di,dj] of [[1,0],[-1,0],[0,1],[0,-1]]){
        const ni2=ring.tx+di, nj2=ring.ty+dj;
        if(ni2<0||nj2<0||ni2>=NI||nj2>=NJ||LAY.maze[nj2][ni2]===1) continue;
        // flee the PREDICTED player position (falls back to current)
        const fr=(predR&&predR[nj2][ni2]>=0)?predR[nj2][ni2]:(distR?distR[nj2][ni2]:0);
        const fb=(predB&&predB[nj2][ni2]>=0)?predB[nj2][ni2]:(distB?distB[nj2][ni2]:fr);
        let score=Math.min(fr,fb);
        // escape-volume: how much room this choice keeps open
        score += D.wEsc * escapeCount(ni2,nj2, blocked, D.floodK||10);
        if(ring.prev && ni2===ring.prev[0] && nj2===ring.prev[1]) score-=2.5;
        if(D.rnd) score+=Math.random()*D.rnd;
        if(score>bestScore){bestScore=score;best=[ni2,nj2];}
      }
    } else {
      // EASY: original greedy one-step brain (unchanged)
      for(const[di,dj] of [[1,0],[-1,0],[0,1],[0,-1]]){
        const ni2=ring.tx+di, nj2=ring.ty+dj;
        if(ni2<0||nj2<0||ni2>=NI||nj2>=NJ||LAY.maze[nj2][ni2]===1) continue;
        const dR=(distR&&distR[nj2][ni2]>=0)?distR[nj2][ni2]:0;
        const dB=(distB&&distB[nj2][ni2]>=0)?distB[nj2][ni2]:dR;
        let score=Math.min(dR,dB);
        if(D.esc){
          let deg=0;
          for(const[ei,ej] of [[1,0],[-1,0],[0,1],[0,-1]]){
            const ai=ni2+ei, aj=nj2+ej;
            if(ai>=0&&aj>=0&&ai<NI&&aj<NJ&&LAY.maze[aj][ai]===0) deg++;
          }
          score+=(deg-2)*D.esc;
        }
        if(ring.prev && ni2===ring.prev[0] && nj2===ring.prev[1]) score-=2.5;
        score+=Math.random()*D.rnd;
        if(score>bestScore){bestScore=score;best=[ni2,nj2];}
      }
    }
    if(best){
      ring.prev=[ring.tx,ring.ty];
      ring.tx=best[0]; ring.ty=best[1];
    }
  } else {
    ring.x += dx/d*ring.speed;
    ring.y += dy/d*ring.speed;
  }
  ring.bob+=0.05;
}

// ---------- drawing ----------
function angLerp(a,b,f){
  let d=b-a;
  while(d>Math.PI)d-=2*Math.PI;
  while(d<-Math.PI)d+=2*Math.PI;
  return a+d*f;
}
const redVis={to:null,from:0,t:99}, blueVis={to:null,from:0,t:99};
function drawActor(body, colorStr){
  if(!body) return;
  let spr_name = colorStr + '_' + body.animState;
  if(body.animState === 'walk'){
     spr_name = colorStr + '_walk' + (Math.floor(body.animT / 8) % 2 + 1);
  }
  let s = SPR[spr_name];
  if(!s) s = SPR[colorStr + '_idle']; // fallback
  if(!s) return;
  
  if(body.face < 0){
    s = SPR[spr_name + '_flip'] || s;
  }
  
  ctx.save();
  ctx.translate(Math.round(body.x) - camX, Math.round(body.y));
  ctx.drawImage(s, -s.width/2, -s.height);
  ctx.restore();
}

function drawLevel() {
  ctx.fillStyle = '#476566'; // Sky color
  ctx.fillRect(0, 0, WNAT, HNAT);
  
  if(SPR.scenery_2x){
    let bgX = (camX * 0.5) % SPR.scenery_2x.width;
    ctx.drawImage(SPR.scenery_2x, -bgX, HNAT - 48 - SPR.scenery_2x.height);
    ctx.drawImage(SPR.scenery_2x, -bgX + SPR.scenery_2x.width, HNAT - 48 - SPR.scenery_2x.height);
  }
  
  ctx.fillStyle = '#38544a'; // Grass line
  ctx.fillRect(0, HNAT-48, WNAT, 48);
  
  ctx.fillStyle = '#02c136'; // Road/blocks
  const startCol = Math.floor(camX / T);
  const endCol = startCol + (WNAT / T) + 1;
  
  for(let j=0; j<NJ; j++){
    for(let i=startCol; i<endCol; i++){
      if(solidCell(i, j)){
        ctx.fillRect(i*T - camX, j*T, T, T);
      }
    }
  }
}

// ---------- fixed-timestep loop: simulation always runs at exactly 60 ticks/s,
// rendering runs at the display's refresh rate (smooth at any Hz) ----------
const STEP=1000/60;
let accT=0, lastT=performance.now();
function loop(now){
  requestAnimationFrame(loop);
  if(now===undefined) now=performance.now();
  let dt=now-lastT; lastT=now;
  if(dt>250) dt=STEP;              // hidden tab / long hiccup: don't fast-forward
  accT+=dt;
  const pads=pollPads();
  lastPadCount=pads.length;
  padEdges(pads);
  let ticks=0;
  while(accT>=STEP && ticks<5){ tick(pads); accT-=STEP; ticks++; }
  if(ticks===5) accT=0;            // machine overloaded: drop the backlog
  render();
  if(crtOn) drawCRT();
}
function padEdges(pads){
  for(let i=0;i<pads.length;i++){
    const pad=pads[i];
    if((pad.jump||pad.start||pad.gx||pad.gy) && soundPref()!=='off'){
      if(!actx) initAudio();
      if(actx.state==='suspended') actx.resume().catch(()=>{});
    }
    const prev=padPrev[i]||{a:false,b:false,jump:false,start:false,gy:0,gx:0,pressed:[]};
    if(state==='title' && titlePhase==='remap'){
      // capture: any newly-pressed button toggles into the current role set
      const now=pad.pressed||[], was=prev.pressed||[];
      for(const idx of now) if(!was.includes(idx)) remapToggle(idx);
      // d-pad navigates the capture flow
      if(pad.gx!==0 && (prev.gx||0)===0) titleNav(Math.sign(pad.gx),0);
      padPrev[i]={a:pad.a,b:pad.b,jump:pad.jump,start:pad.start,gy:pad.gy,gx:pad.gx,pressed:now};
      continue;
    }
    if(state==='title'){
      if(pad.gy!==0 && (prev.gy||0)===0) titleNav(0,Math.sign(pad.gy));
      if(pad.gx!==0 && (prev.gx||0)===0) titleNav(Math.sign(pad.gx),0);
      if(pad.a&&!prev.a) titleAdvance();
      else if(pad.start&&!prev.start) titleAdvance();
      if(pad.b&&!prev.b) titleBack();
      padPrev[i]={a:pad.a,b:pad.b,jump:pad.jump,start:pad.start,gy:pad.gy,gx:pad.gx,pressed:pad.pressed};
      continue;
    }
    // pad 0 drives red; pad 1 drives blue in 2P
    const target = (i===0) ? player : (players===2 && blueW && i===1 ? blueW : null);
    if(pad.jump&&!prev.jump){
      if(state==='play' && target) target.jump(J);
      else if(state==='won') reset();
      else if(state==='paused'){ if(pad.b&&!prev.b) state='play'; else pauseConfirm(); }
    }
    // B backs out of the pause menu straight to resume
    if(state==='paused' && pad.b && !prev.b && !(pad.jump&&!prev.jump)) state='play';
    if(target){
      if(pad.jump) target.jheld=true;
      else if(prev.jump) target.jheld=false;
    }
    if(pad.start&&!prev.start){
      if(state==='won') reset();
      else if(state==='paused') pauseConfirm();
      else if(state==='play') togglePause();
    }
    if(state==='paused' && pad.gy!==0 && (prev.gy||0)===0) pauseSel=(pauseSel+1)%2;
    padPrev[i]={a:pad.a,b:pad.b,jump:pad.jump,start:pad.start,gy:pad.gy,gx:pad.gx};
  }
  padPrev.length=pads.length;
}
function tick(pads){
  frame++;
  if(frame%90===0 && actx && actx.state==='suspended' && soundPref()!=='off')
    actx.resume().catch(()=>{});
  if(state==='title'){ titleUpdate(); return; }
  if(state==='play'){
    const kx=(keys.ArrowLeft||keys.KeyA?-1:0)+(keys.ArrowRight||keys.KeyD?1:0);
    const ky=(keys.ArrowUp||keys.KeyW?-1:0)+(keys.ArrowDown||keys.KeyS?1:0);
    const p0=pads[0], p1=pads[1];
    // red: pad 0; in 1P the keyboard and touch drive red too
    let rx=p0?p0.gx:0, ry=p0?p0.gy:0;
    if(players===1){ rx=rx||kx||touchIn.x; ry=ry||ky||touchIn.y; }
    player.drive(rx,ry,ACC,MAX,FRIC,SKID);
    player.airControl(rx,ry);
    player.step();
    if(players===2 && blueW){
      // blue: keyboard (P2), plus pad 1 when two controllers are connected
      let bx=kx||touchIn.x, by=ky||touchIn.y;
      if(p1){ bx=bx||p1.gx; by=by||p1.gy; }
      blueW.drive(bx,by,ACC,MAX,FRIC,SKID);
      blueW.airControl(bx,by);
      blueW.step();
    } else {
      trail.push({x:player.x,y:player.y,n:{...player.n},face:player.face,animT:player.animT,air:player.air});
      if(trail.length>400) trail.shift();
    }
    if(frame%20===0) bfs();
    bossStep();
    // Level end check
    if(player.x > (NI-4) * T){
        state='won';
        winFx={x:player.x, y:player.y, t:0, holder:player};
        if(music&&!music.muted) jingle();
        if(music&&!music.muted) jingle();
    }
  }
  if(state==='won' && winFx) winFx.t++;
}
function soundHint(){
  if(actx && actx.state==='suspended' && music && !music.muted && lastPadCount>0 && frame%80<55)
    pixText(ctx,'CLICK FOR SOUND', WNAT/2, HNAT-5*4-10, 4, F35,3,5, '#c8b890','#8a7758', true);
}
function render(){
  if(state==='title'){
    // --- render title ---
    ctx.fillStyle='#070402'; ctx.fillRect(0,0,WNAT,HNAT);
    ctx.drawImage(dirtFor(LAY.title),0,0);
    // blue trails, red chases
    const tbs=trailFollow();
    
    drawWalker(null,SPR.redA,SPR.redB,
      {x:tRed.x,y:tRed.y,n:tRed.n,face:tRed.face,animT:tRed.animT},redVis);
    // the ring hovers just off its surface, glowing
    const rx=tRing.x+tRing.n.x*26, ry=tRing.y+tRing.n.y*26 + Math.sin(frame*0.08)*2;
    const gg=ctx.createRadialGradient(rx,ry,4,rx,ry,70);
    gg.addColorStop(0,'rgba(255,230,150,0.20)'); gg.addColorStop(1,'rgba(255,230,150,0)');
    ctx.fillStyle=gg; ctx.fillRect(rx-70,ry-70,140,140);
    
    if (SPR.boss_body_angry) {
      ctx.drawImage(SPR.boss_body_angry, Math.round(rx - SPR.boss_body_angry.width/2) - camX, Math.round(ry - SPR.boss_body_angry.height/2));
      if (SPR.boss_propeller) {
         ctx.drawImage(SPR.boss_propeller, Math.round(rx - SPR.boss_propeller.width/2) - camX, Math.round(ry - SPR.boss_body_angry.height/2 - 20));
      }
    }

    // logo on the island
    const logoH = 2*7*LAY.logoPx + 10;                 // two lines + gap
    const logoY = ISL.y0 + (ISLH - logoH)/2;           // centred on the block
    pixText(ctx,'RING', WNAT/2, logoY, LAY.logoPx, F57,5,7, '#f8d838','#c8952c', true);
    pixText(ctx,'CHASE',WNAT/2, logoY+7*LAY.logoPx+10, LAY.logoPx, F57,5,7, '#f8d838','#c8952c', true);
    if(titlePhase==='mode'){
      // -------- game-mode selector --------
      const px=LAY.promptPx;
      const opts=['FOLLOW THE LEADER','SOLO'];
      for(let i=0;i<2;i++){
        const y=ISL.y1+1.5*T + i*(5*px+14);
        const sel=i===modeSel;
        pixText(ctx,(sel?'> ':'  ')+opts[i]+(sel?' <':'  '), WNAT/2, y, px, F35,3,5,
                sel?'#f8f0dc':'#7d6a50', sel?'#c8b890':'#5e5040', true);
      }
    } else if(titlePhase==='char'){
      // -------- simple hero selector --------
      const px=LAY.promptPx;
      pixText(ctx,'PLAYER 1', WNAT/2, ISL.y1+1.1*T, px, F35,3,5, '#f8f0dc','#c8b890', true);
      const sc=1.6, gap=WNAT*0.16;
      const chars=[{spr:SPR.redA},{spr:SPR.blueA}];
      const baseY=ISL.y1+1.1*T + 5*px + 18;
      for(let i=0;i<2;i++){
        const spr=chars[i].spr;
        const w=spr.width*sc, h=spr.height*sc;
        const cxx=WNAT/2 + (i===0?-gap:gap);
        const sel=i===charSel;
        const bob=sel?Math.sin(frame*0.12)*3:0;
        ctx.save();
        ctx.globalAlpha=sel?1:0.42;
        ctx.imageSmoothingEnabled=false;
        ctx.drawImage(spr, Math.round(cxx-w/2), Math.round(baseY+bob), Math.round(w), Math.round(h));
        ctx.restore();
        if(sel){
          pixText(ctx,'>', cxx-w/2-14, baseY+h*0.4, px, F35,3,5, '#f8d838','#c8952c', true);
          pixText(ctx,'<', cxx+w/2+14, baseY+h*0.4, px, F35,3,5, '#f8d838','#c8952c', true);
        }
      }
    } else if(titlePhase==='settings'){
      // -------- settings panel: name left, < value > right of the selected row --------
      const px=LAY.promptPx;
      const rows=[['MUSIC',       musicOn()?'ON':'OFF'],
                  ['DIFFICULTY',  DIFFS[diffSel].name],
                  ['CRT',         crtOn?'ON':'OFF'],
                  ['CONTROLS',    null]];
      for(let i=0;i<rows.length;i++){
        const y=ISL.y1+1.2*T + i*(5*px+13);
        const sel=i===setSel;
        const [name,val]=rows[i];
        let label;
        if(val===null) label = sel ? '> '+name+' <' : '  '+name+'  ';
        else label = name+'  '+(sel?'< ':'  ')+val+(sel?' >':'  ');
        pixText(ctx,label, WNAT/2, y, px, F35,3,5,
                sel?'#f8f0dc':'#7d6a50', sel?'#c8b890':'#5e5040', true);
      }
    } else if(titlePhase==='remap'){
      // -------- controller button remap (any count per role) --------
      const px=Math.max(3,LAY.promptPx-1);
      const capturing = remapStep===0 ? 'ACCEPT' : 'BACK';
      pixText(ctx,'STEP '+(remapStep+1)+' OF 2', WNAT/2, ISL.y1+0.55*T, Math.max(2,px-1), F35,3,5, '#a89060','#7d6a50', true);
      pixText(ctx,'SET '+capturing+' BUTTONS', WNAT/2, ISL.y1+0.9*T, px, F35,3,5, '#f8f0dc','#c8b890', true);
      pixText(ctx,'PRESS BUTTONS TO TOGGLE', WNAT/2, ISL.y1+0.9*T+5*px+14, Math.max(2,px-1), F35,3,5, '#a89060','#7d6a50', true);
      // live assigned lists via the crisp monospace font
      ctx.textAlign='center';
      const fs=Math.max(16, Math.round(WNAT*0.024));
      ctx.font='bold '+fs+'px monospace';
      const acc=[...wAccept].sort((a,b)=>a-b), bak=[...wBack].sort((a,b)=>a-b);
      const yA=ISL.y1+0.9*T+5*px+14 + 5*Math.max(2,px-1)+ fs+18;
      ctx.fillStyle = remapStep===0 ? '#8fe0a0' : '#6a8a72';
      ctx.fillText('ACCEPT: '+(acc.length?acc.join(' '):'-'), WNAT/2, yA);
      ctx.fillStyle = remapStep===1 ? '#f0b060' : '#8a7350';
      ctx.fillText('BACK: '+(bak.length?bak.join(' '):'-'), WNAT/2, yA+fs+10);
      if(remapLast>=0){
        ctx.fillStyle='#e8d8b0'; ctx.font=Math.round(fs*0.8)+'px monospace';
        ctx.fillText('last pressed: '+remapLast, WNAT/2, yA+2*(fs+10));
      }
    } else {
      // -------- main menu list --------
      const px=LAY.promptPx;
      const it=menuItems();
      if(menuSel>=it.length) menuSel=it.length-1;
      for(let i=0;i<it.length;i++){
        const y=ISL.y1+1.4*T + i*(5*px+14);
        const sel=i===menuSel;
        pixText(ctx,(sel?'> ':'  ')+it[i]+(sel?' <':'  '), WNAT/2, y, px, F35,3,5,
                sel?'#f8f0dc':'#7d6a50', sel?'#c8b890':'#5e5040', true);
      }
    }
    // footer hint on sub-screens
    if(titlePhase!=='menu'){
      const px=Math.max(3,LAY.promptPx-1);
      const hint = titlePhase==='settings' ? 'CHANGE   A SELECT   B DONE'
                 : titlePhase==='remap' ? (remapStep===0 ? 'DPAD RIGHT NEXT   LEFT CANCEL' : 'DPAD RIGHT SAVE   LEFT PREV')
                 : 'A SELECT   B BACK';
      pixText(ctx,hint, WNAT/2, HNAT-6*px, px, F35,3,5, '#8a7758','#5e5040', true);
    }
    // cozy vignette
    const tv=ctx.createRadialGradient(WNAT/2,HNAT/2,HNAT*0.45,WNAT/2,HNAT/2,HNAT*1.05);
    tv.addColorStop(0,'rgba(0,0,0,0)'); tv.addColorStop(1,'rgba(15,6,0,0.30)');
    ctx.fillStyle=tv; ctx.fillRect(0,0,WNAT,HNAT);
    soundHint();
    return;
  }

  // render
  ctx.fillStyle='#070402';
  ctx.fillRect(0,0,WNAT,HNAT);
  ctx.drawImage(dirtFor(LAY.maze),0,0);

  // ring (not animated, just moves) with a soft warm glow.
  // once caught, the world ring disappears — it's drawn in the player's hands instead
  if(state!=='won'){
    // teleport scale/alpha: shrink out (phase 1) then pop in (phase 2)
    let scale=1, alpha=1;
    if(ring.tpPhase===1){ const p=Math.min(ring.tpT/8,1); scale=1-p*0.9; alpha=1-p; }
    else if(ring.tpPhase===2){ const p=Math.min(ring.tpT/8,1); scale=0.1+p*0.9; alpha=p; }
    const g=ctx.createRadialGradient(ring.x,ring.y,4,ring.x,ring.y,70);
    g.addColorStop(0,'rgba(255,230,150,'+(0.20*alpha).toFixed(3)+')'); g.addColorStop(1,'rgba(255,230,150,0)');
    ctx.fillStyle=g; ctx.fillRect(ring.x-70,ring.y-70,140,140);
    // a bright flash ring at the moment of vanish / arrival
    if(ring.tpPhase>0){
      const fp = ring.tpPhase===1 ? ring.tpT/8 : 1-ring.tpT/8;
      const fr = 12 + fp*54;
      ctx.save();
      ctx.globalAlpha=Math.max(0,0.85*fp);
      ctx.strokeStyle='#fff2c8'; ctx.lineWidth=4;
      ctx.beginPath(); ctx.arc(ring.x,ring.y,fr,0,Math.PI*2); ctx.stroke();
      ctx.restore();
    }
    ctx.save();
    ctx.globalAlpha=Math.max(0,alpha);
    ctx.translate(ring.x,ring.y); ctx.scale(scale,scale);
    
    if (SPR.boss_body_angry) {
      ctx.drawImage(SPR.boss_body_angry, Math.round(rx - SPR.boss_body_angry.width/2) - camX, Math.round(ry - SPR.boss_body_angry.height/2));
      if (SPR.boss_propeller) {
         ctx.drawImage(SPR.boss_propeller, Math.round(rx - SPR.boss_propeller.width/2) - camX, Math.round(ry - SPR.boss_body_angry.height/2 - 20));
      }
    }

    ctx.restore();
  }

  // sprite assignment: in 1P the chosen hero is player-controlled, the other follows
  const heroRed = players===2 || p1Char==='red';
  const P1S = heroRed ? {a:SPR.redA,b:SPR.redB,vis:redVis} : {a:SPR.blueA,b:SPR.blueB,vis:blueVis};
  const P2S = heroRed ? {a:SPR.blueA,b:SPR.blueB,vis:blueVis} : {a:SPR.redA,b:SPR.redB,vis:redVis};
  if(players===2 && blueW){
    drawActor(blueW, 'yellow');
  } else if(!soloMode){
    // follow-the-leader: the other character trails behind
    const bs = trailFollow();
    
    
  }
  // solo: no trailing buddy drawn at all
  drawActor(player, p1Char);

  // gentle warm vignette (warmth lives in the dirt palette; corridors stay deep dark)
  const vg=ctx.createRadialGradient(WNAT/2,HNAT/2,HNAT*0.45,WNAT/2,HNAT/2,HNAT*1.05);
  vg.addColorStop(0,'rgba(0,0,0,0)'); vg.addColorStop(1,'rgba(15,6,0,0.30)');
  ctx.fillStyle=vg; ctx.fillRect(0,0,WNAT,HNAT);
  soundHint();

  if(state==='paused'){
    ctx.fillStyle='rgba(0,0,0,0.55)'; ctx.fillRect(0,0,WNAT,HNAT);
    ctx.textAlign='center';
    const fp=Math.min(46, WNAT*0.075);
    ctx.font='bold '+fp+'px monospace';
    ctx.fillStyle='#1a0d04'; ctx.fillText('PAUSED', WNAT/2+3, HNAT/2-fp*1.1+3);
    ctx.fillStyle='#f8e8b0'; ctx.fillText('PAUSED', WNAT/2, HNAT/2-fp*1.1);
    const px=LAY.promptPx;
    const opts=['RESUME','MAIN MENU'];
    for(let i=0;i<2;i++){
      const y=HNAT/2 - fp*0.4 + i*(5*px+14);
      const sel=i===pauseSel;
      pixText(ctx,(sel?'> ':'  ')+opts[i]+(sel?' <':'  '), WNAT/2, y, px, F35,3,5,
              sel?'#f8f0dc':'#7d6a50', sel?'#c8b890':'#5e5040', true);
    }
  }

  if(state==='won'){
    // Darken background
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0,0,WNAT,HNAT);
    
    // Draw Victory UI
    if(SPR.victory_overlay){
        ctx.drawImage(SPR.victory_overlay, 0, 0);
    }
}
function drawTitle(){
  // Character Select Screen
  ctx.fillStyle = '#000';
  ctx.fillRect(0,0,WNAT,HNAT);
  
  ctx.strokeStyle = '#222';
  ctx.lineWidth = 1;
  for(let x=0; x<WNAT; x+=24) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,HNAT); ctx.stroke(); }
  for(let y=0; y<HNAT; y+=24) { ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(WNAT,y); ctx.stroke(); }
  
  ctx.fillStyle = '#0f0';
  ctx.font = '20px monospace';
  ctx.textAlign = 'center';
  ctx.fillText('CHOOSE YOUR MOUSE', WNAT/2, 40);
  
  const mice = ['pink', 'cyan', 'yellow'];
  const colors = ['#ff00ff', '#00ffff', '#ffff00'];
  
  for(let i=0; i<3; i++) {
    const x = WNAT/4 * (i+1);
    const y = HNAT/2 + 20;
    
    ctx.fillStyle = colors[i];
    ctx.beginPath();
    ctx.ellipse(x, y + 20, 25, 8, 0, 0, Math.PI*2);
    ctx.fill();
    
    if(charSel === i){
       ctx.strokeStyle = '#fff';
       ctx.lineWidth = 3;
       ctx.stroke();
    }
    
    const spr = SPR[mice[i] + '_idle'];
    if(spr) {
       ctx.drawImage(spr, x - spr.width/2, y - spr.height/2 + (charSel===i ? Math.sin(Date.now()/100)*3 : 0));
    }
  }
  
  ctx.fillStyle = '#fff';
  ctx.font = '12px monospace';
  if(Math.floor(Date.now()/500)%2===0) {
    ctx.fillText('PRESS JUMP TO START', WNAT/2, HNAT - 30);
  }
}

function titleUpdate(){
  if(pad.gx === 1 && (!padPrev || !padPrev.gx)) charSel = (charSel + 1) % 3;
  if(pad.gx === -1 && (!padPrev || !padPrev.gx)) charSel = (charSel + 2) % 3;
  if(pad.jump && (!padPrev || !padPrev.jump)) {
     p1Char = ['pink', 'cyan', 'yellow'][charSel];
     beginPlay(1);
  }
}

}
